import{_ as a,c as i,o as t,ae as o}from"./chunks/framework.BGWP4WZ_.js";const r="/py-xiaozhi/assets/logo.DvtHcDKz.png",m=JSON.parse('{"title":"open-xiaoai","description":"An open-source project that lets your XiaoAI Speaker \\"hear your voice\\" and unlocks unlimited possibilities","frontmatter":{"title":"open-xiaoai","description":"An open-source project that lets your XiaoAI Speaker \\"hear your voice\\" and unlocks unlimited possibilities"},"headers":[],"relativePath":"ecosystem/projects/open-xiaoai/index.md","filePath":"ecosystem/projects/open-xiaoai/index.md"}'),s={name:"ecosystem/projects/open-xiaoai/index.md"};function n(l,e,c,p,d,h){return t(),i("div",null,e[0]||(e[0]=[o('<h1 id="open-xiaoai" tabindex="-1">open-xiaoai <a class="header-anchor" href="#open-xiaoai" aria-label="Permalink to &quot;open-xiaoai&quot;">​</a></h1><div class="project-header"><div class="project-logo"><img src="https://avatars.githubusercontent.com/u/35302658?s=48&amp;v=4" alt="open-xiaoai Logo"></div><div class="project-badges"><span class="badge platform">Cross-platform</span><span class="badge language">Rust/Python/Node.js</span><span class="badge status">Experimental</span></div></div><div class="project-banner"><img src="'+r+'" alt="Open-XiaoAI Project Banner"></div><h2 id="project-overview" tabindex="-1">Project Overview <a class="header-anchor" href="#project-overview" aria-label="Permalink to &quot;Project Overview&quot;">​</a></h2><p>Open-XiaoAI is an open-source project that lets your XiaoAI Speaker &quot;hear your voice&quot; and seamlessly integrates it with the XiaoZhi AI ecosystem. The project directly takes over the &quot;ears&quot; and &quot;mouth&quot; of the XiaoAI Speaker, fully unleashing its potential through multimodal large models and AI Agent technology, unlocking unlimited possibilities.</p><p>In 2017, when the world&#39;s first smart speaker with tens of millions of sales was born, we thought we had touched the future. But soon we realized these devices were trapped in a &quot;command-response&quot; cage:</p><ul><li>It can hear decibels, but not understand emotions</li><li>It can execute commands, but not think proactively</li><li>It has millions of users, but only one way of thinking</li></ul><p>The &quot;Jarvis&quot;-level AI we imagined has become just an &quot;alarm clock + music player&quot; in reality.</p><p><strong>True intelligence should not be bound by preset code logic, but should evolve through interaction like a living being.</strong></p><p>Building on the previous <a href="https://github.com/idootop/mi-gpt" target="_blank" rel="noreferrer">MiGPT</a> project, Open-XiaoAI evolves again, providing a new way for the XiaoZhi ecosystem to interact with the XiaoAI Speaker.</p><h2 id="core-features" tabindex="-1">Core Features <a class="header-anchor" href="#core-features" aria-label="Permalink to &quot;Core Features&quot;">​</a></h2><div class="features-grid"><div class="feature-card"><div class="feature-icon">🎤</div><h3>Voice Input Takeover</h3><p>Directly captures the XiaoAI Speaker&#39;s microphone input, bypassing original speech recognition limitations</p></div><div class="feature-card"><div class="feature-icon">🔊</div><h3>Audio Output Control</h3><p>Fully takes over the speaker, allowing playback of custom audio and TTS content</p></div><div class="feature-card"><div class="feature-icon">🧠</div><h3>AI Model Integration</h3><p>Supports integration with XiaoZhi AI, ChatGPT, and other large models for natural conversation</p></div><div class="feature-card"><div class="feature-icon">🌐</div><h3>Cross-platform Support</h3><p>Client is developed in Rust; Server supports Python and Node.js implementations</p></div><div class="feature-card"><div class="feature-icon">🛠️</div><h3>Extensible Architecture</h3><p>Modular design makes it easy for developers to add custom features and integrate other services</p></div><div class="feature-card"><div class="feature-icon">🎮</div><h3>Developer Friendly</h3><p>Detailed documentation and tutorials help developers get started quickly and customize features</p></div></div><h2 id="demo-videos" tabindex="-1">Demo Videos <a class="header-anchor" href="#demo-videos" aria-label="Permalink to &quot;Demo Videos&quot;">​</a></h2><div class="demo-videos"><div class="video-item"><a href="https://www.bilibili.com/video/BV1NBXWYSEvX" target="_blank" class="video-link"><div class="video-thumbnail"><img src="https://raw.githubusercontent.com/idootop/open-xiaoai/main/docs/images/xiaozhi.jpg" alt="XiaoAI Speaker with XiaoZhi AI"></div><div class="video-title"><span class="video-icon">▶️</span><span>XiaoAI Speaker with XiaoZhi AI Demo</span></div></a></div><div class="video-item"><a href="https://www.bilibili.com/video/BV1N1421y7qn" target="_blank" class="video-link"><div class="video-thumbnail"><img src="https://github.com/idootop/open-xiaoai/raw/main/docs/images/migpt.jpg" alt="XiaoAI Speaker with MiGPT"></div><div class="video-title"><span class="video-icon">▶️</span><span>XiaoAI Speaker with MiGPT Demo</span></div></a></div></div><h2 id="quick-start" tabindex="-1">Quick Start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick Start&quot;">​</a></h2><div class="important-notice"><div class="notice-icon">⚠️</div><div class="notice-content"><strong>Important Notice</strong><p>This tutorial is only applicable to <strong>XiaoAI Speaker Pro (LX06)</strong> and <strong>Xiaomi Smart Speaker Pro (OH2P)</strong>. <strong>Do not use</strong> with other models!</p></div></div><p>The Open-XiaoAI project consists of a Client and a Server. You can get started quickly by following these steps:</p><h3 id="installation-steps" tabindex="-1">Installation Steps <a class="header-anchor" href="#installation-steps" aria-label="Permalink to &quot;Installation Steps&quot;">​</a></h3><div class="steps"><div class="step"><div class="step-number">1</div><div class="step-content"><h4>XiaoAI Speaker Firmware Update</h4><p>Flash the patched firmware to your XiaoAI Speaker, enable SSH, and connect to the speaker</p><a href="https://github.com/idootop/open-xiaoai/blob/main/docs/flash.md" target="_blank" class="step-link">View detailed tutorial</a></div></div><div class="step"><div class="step-number">2</div><div class="step-content"><h4>Client Deployment</h4><p>Compile the Client patch program on your computer, then copy it to the speaker and run it</p><a href="https://github.com/idootop/open-xiaoai/blob/main/packages/client-rust/README.md" target="_blank" class="step-link">View detailed tutorial</a></div></div><div class="step"><div class="step-number">3</div><div class="step-content"><h4>Server Deployment</h4><p>Run the Server demo program on your computer to experience the new capabilities of the XiaoAI Speaker</p><ul class="step-options"><li><a href="https://github.com/idootop/open-xiaoai/blob/main/packages/server-python/README.md" target="_blank">Python Server - XiaoAI Speaker with XiaoZhi AI</a></li><li><a href="https://github.com/idootop/open-xiaoai/blob/main/packages/server-node/README.md" target="_blank">Node.js Server - XiaoAI Speaker with MiGPT-Next</a></li></ul></div></div></div><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2><p>Open-XiaoAI works as follows:</p><ol><li><strong>Firmware Patch</strong>: Modifies the XiaoAI Speaker firmware to allow SSH access and low-level system control</li><li><strong>Audio Stream Hijacking</strong>: The client program directly captures microphone input and controls speaker output</li><li><strong>Network Communication</strong>: The client and server establish a WebSocket connection for real-time communication</li><li><strong>AI Processing</strong>: The server receives voice input, processes it with an AI model, and returns the response</li><li><strong>Custom Features</strong>: Developers can implement various custom features and integrations on the server</li></ol><h2 id="related-projects" tabindex="-1">Related Projects <a class="header-anchor" href="#related-projects" aria-label="Permalink to &quot;Related Projects&quot;">​</a></h2><p>If you don&#39;t want to flash firmware or don&#39;t have a XiaoAI Speaker Pro, the following projects may be useful:</p><ul><li><a href="https://github.com/idootop/mi-gpt" target="_blank" rel="noreferrer">MiGPT</a> - The original project to connect ChatGPT to XiaoAI Speaker</li><li><a href="https://github.com/idootop/migpt-next" target="_blank" rel="noreferrer">MiGPT-Next</a> - The next generation of MiGPT</li><li><a href="https://github.com/yihong0618/xiaogpt" target="_blank" rel="noreferrer">XiaoGPT</a> - Another ChatGPT integration for XiaoAI Speaker</li><li><a href="https://github.com/hanxi/xiaomusic" target="_blank" rel="noreferrer">XiaoMusic</a> - Enhanced music playback for XiaoAI Speaker</li></ul><h2 id="technical-references" tabindex="-1">Technical References <a class="header-anchor" href="#technical-references" aria-label="Permalink to &quot;Technical References&quot;">​</a></h2><p>If you want to learn more technical details, the following links may help:</p><ul><li><a href="https://github.com/duhow/xiaoai-patch" target="_blank" rel="noreferrer">xiaoai-patch</a> - XiaoAI Speaker firmware patch</li><li><a href="https://github.com/jialeicui/open-lx01" target="_blank" rel="noreferrer">open-lx01</a> - Open-source project for XiaoAI Speaker LX01</li><li><a href="https://javabin.cn/2021/xiaoai_fm.html" target="_blank" rel="noreferrer">XiaoAI FM Research</a> - Research on XiaoAI Speaker FM functionality</li><li><a href="https://github.com/yihong0618/gitblog/issues/258" target="_blank" rel="noreferrer">Xiaomi Device Security Research</a> - Xiaomi IoT device security analysis</li><li><a href="https://xuanxuanblingbling.github.io/iot/2022/09/16/mi/" target="_blank" rel="noreferrer">XiaoAI Speaker Exploration</a> - Technical exploration of XiaoAI Speaker</li></ul><h2 id="disclaimer" tabindex="-1">Disclaimer <a class="header-anchor" href="#disclaimer" aria-label="Permalink to &quot;Disclaimer&quot;">​</a></h2><div class="disclaimer"><h4>Scope of Use</h4><p>This project is a non-profit open-source project, intended only for technical research, security vulnerability verification, and non-commercial personal use. It is strictly prohibited to use for commercial services, network attacks, data theft, system destruction, or any scenarios that violate the Cybersecurity Law or the laws of your jurisdiction.</p><h4>Unofficial Statement</h4><p>This project is independently developed by third-party developers and has no affiliation, cooperation, authorization, or technical support from Xiaomi Group or its affiliates (&quot;the rights holder&quot;). All rights to trademarks, firmware, and cloud services mentioned in the project belong to Xiaomi Group. If the rights holder asserts their rights, users should immediately stop using and delete this project.</p><p>By continuing to use this project, you acknowledge that you have read and agree to the <a href="https://github.com/idootop/open-xiaoai/blob/main/agreement.md" target="_blank">User Agreement</a>. Otherwise, please stop using and delete this project immediately.</p></div><h2 id="license" tabindex="-1">License <a class="header-anchor" href="#license" aria-label="Permalink to &quot;License&quot;">​</a></h2><p>This project uses the <a href="https://github.com/idootop/open-xiaoai/blob/main/LICENSE" target="_blank" rel="noreferrer">MIT</a> License © 2024-PRESENT Del Wang</p>',32)]))}const v=a(s,[["render",n]]);export{m as __pageData,v as default};
